changeSet.sql:
CREATE TABLE AI_SESSION ( id VARCHAR(255) NOT NULL PRIMARY KEY, created_at TIMESTAMP NOT NULL, expires_at TIMESTAMP, metadata TEXT NOT NULL, event_version BIGINT NOT NULL DEFAULT 0 );
CREATE INDEX idx_ai_session_expires_at ON AI_SESSION (expires_at);
CREATE TABLE AI_SESSION_INDEX ( session_id VARCHAR(255) NOT NULL, attr_name VARCHAR(255) NOT NULL, attr_value VARCHAR(512) NOT NULL, PRIMARY KEY (session_id, attr_name), CONSTRAINT fk_ai_session_index_session FOREIGN KEY (session_id) REFERENCES AI_SESSION (id) ON DELETE CASCADE );
CREATE INDEX idx_ai_session_index_name_value ON AI_SESSION_INDEX (attr_name, attr_value);
CREATE TABLE AI_SESSION_EVENT ( seq BIGINT GENERATED BY DEFAULT AS IDENTITY, id VARCHAR(255) NOT NULL PRIMARY KEY, session_id VARCHAR(255) NOT NULL, "timestamp" TIMESTAMP NOT NULL, event_type VARCHAR(64) NOT NULL DEFAULT 'MESSAGE', message_type VARCHAR(20), message_content TEXT, payload TEXT NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT FALSE, metadata TEXT NOT NULL, CONSTRAINT fk_ai_session_event_session FOREIGN KEY (session_id) REFERENCES AI_SESSION (id) ON DELETE CASCADE );
CREATE INDEX idx_ai_session_event_session_seq ON AI_SESSION_EVENT (session_id, seq);
CREATE INDEX idx_ai_session_event_session_type_seq ON AI_SESSION_EVENT (session_id, event_type, seq);
